def find_lexicographically_smallest_permutation(K, permutation, exchange_matrices):
    from itertools import permutations

    def can_swap(i, j, exchange_matrices):
        return exchange_matrices[i][j] == 'Y'

    def generate_permutations(original, exchange_matrices):
        for perm in permutations(original):
            yield list(perm)
            for i in range(K):
                for j in range(K):
                    if can_swap(i, j, exchange_matrices):
                        perm_list = list(perm)
                        perm_list[i], perm_list[j] = perm_list[j], perm_list[i]
                        yield perm_list

    original_permutation = list(permutation)
    min_permutation = None

    for perm in generate_permutations(original_permutation, exchange_matrices):
        if min_permutation is None or perm < min_permutation:
            min_permutation = perm

    return min_permutation

